INSERT INTO employee_education (
  employee_id, education_type, education_degree, institution_name,
  speciality, started_at, ended_at, document_number, created_at, updated_at
)
SELECT
  id,
  'higher',
  'Бакалавр',
  CASE id % 5
    WHEN 0 THEN 'Таджикский национальный университет'
    WHEN 1 THEN 'Российско-Таджикский (Славянский) университет'
    WHEN 2 THEN 'Таджикский технический университет имени М. Осими'
    WHEN 3 THEN 'Филиал МГУ имени М.В. Ломоносова в городе Душанбе'
    ELSE 'Таджикский государственный университет коммерции'
  END,
  CASE id % 5
    WHEN 0 THEN 'Управление персоналом'
    WHEN 1 THEN 'Информационные технологии'
    WHEN 2 THEN 'Финансы и кредит'
    WHEN 3 THEN 'Менеджмент'
    ELSE 'Маркетинг'
  END,
  printf('%d-09-01', 2008 + (id % 10)),
  printf('%d-06-30', 2012 + (id % 10)),
  printf('DIP-%d-%03d', 2012 + (id % 10), id),
  '2026-06-22 10:00:00',
  '2026-06-22 10:00:00'
