INSERT INTO employee_experience (
  employee_id, company_name, position_name, started_at, ended_at,
  is_current, responsibilities, created_at, updated_at
)
SELECT
  id,
  CASE id % 6
    WHEN 0 THEN 'Tcell'
    WHEN 1 THEN 'Alif Bank'
    WHEN 2 THEN 'MegaFon Tajikistan'
    WHEN 3 THEN 'Eskhata'
    WHEN 4 THEN 'Dushanbe City'
    ELSE 'ZET-MOBILE'
  END,
  CASE id % 5
    WHEN 0 THEN 'Специалист'
    WHEN 1 THEN 'Ведущий специалист'
    WHEN 2 THEN 'Менеджер'
    WHEN 3 THEN 'Инженер'
    ELSE 'Аналитик'
  END,
  printf('%d-02-01', 2016 + (id % 5)),
  printf('%d-01-20', 2018 + (id % 5)),
  0,
  'Работа по профильному направлению, участие в проектах и внутренних процессах.',
  '2026-06-22 10:15:00',
  '2026-06-22 10:15:00'
FROM employees
WHERE id BETWEEN 6 AND 29;

