INSERT INTO candidate_skill_scores (
  candidate_id, vacancy_skill_id, score, created_at, updated_at
)
SELECT
  c.id,
  s.id,
  5 + ((c.id + s.id) % 6),
  c.created_at,
  c.created_at
FROM candidates c
JOIN vacancy_skills s ON s.vacancy_id = c.vacancy_id;

UPDATE candidates SET status='screening' WHERE id BETWEEN 8 AND 13;

UPDATE candidates SET status='screening' WHERE id BETWEEN 14 AND 18;
UPDATE candidates SET status='interview' WHERE id BETWEEN 14 AND 18;

UPDATE candidates SET status='screening' WHERE id BETWEEN 19 AND 21;
UPDATE candidates SET status='interview' WHERE id BETWEEN 19 AND 21;
UPDATE candidates SET status='offer' WHERE id BETWEEN 19 AND 21;

UPDATE candidates SET status='rejected' WHERE id IN (22,26,30);
UPDATE candidates SET status='screening' WHERE id IN (23,27,31);
UPDATE candidates SET status='rejected' WHERE id IN (23,27,31);
UPDATE candidates SET status='screening' WHERE id IN (24,28);
UPDATE candidates SET status='interview' WHERE id IN (24,28);
UPDATE candidates SET status='rejected' WHERE id IN (24,28);
