WITH RECURSIVE seq(n) AS (
  SELECT 1
  UNION ALL
  SELECT n+1 FROM seq WHERE n<72
)
INSERT INTO audit_events (
  occurred_at,actor_account_type,actor_account_id,actor_username,
  action,entity_type,entity_id,before_json,after_json,metadata_json,
  enterprise_id,department_id
)
SELECT
  datetime('2026-06-22 08:00:00','+'||(n*27)||' hours'),
  'system_admin',1,'superadmin',
  CASE n % 11
    WHEN 0 THEN 'employee.create'
    WHEN 1 THEN 'employee.update'
    WHEN 2 THEN 'employee.change_employment'
    WHEN 3 THEN 'vacation.create'
    WHEN 4 THEN 'vacation.approve'
    WHEN 5 THEN 'vacancy.create'
    WHEN 6 THEN 'candidate.create'
    WHEN 7 THEN 'candidate.advance'
    WHEN 8 THEN 'document.add'
    WHEN 9 THEN 'role.assign'
    ELSE 'data.export'
  END,
  CASE n % 11
    WHEN 3 THEN 'vacation'
    WHEN 4 THEN 'vacation'
    WHEN 5 THEN 'vacancy'
    WHEN 6 THEN 'candidate'
    WHEN 7 THEN 'candidate'
    WHEN 8 THEN 'employee_document'
    WHEN 9 THEN 'user_role'
    WHEN 10 THEN 'data_exchange'
    ELSE 'employee'
  END,
  ((n-1)%45)+1,
  CASE WHEN n%3=0 THEN '{"status":"before"}' ELSE NULL END,
  '{"status":"after","source":"presentation"}',
  '{"source":"presentation_seed"}',
  (SELECT enterprise_id FROM employees WHERE id=((n-1)%45)+1),
  (SELECT department_id FROM employees WHERE id=((n-1)%45)+1)
FROM seq;

COMMIT;
